(function(){
  'use strict';
  if(window.EDUTRACK_SCHOOL_GUIDE)return;
  var TOUR_KEY='edutrack_school_guide_tour_completed_v1';
  var SECTIONS=[
    {id:'overview',title:'Overview',body:'EduTrack is an integrated school management and education tracking system. The functions you can see depend on your role, permissions, assigned responsibilities, class or subject assignment, school type, and subscription status.'},
    {id:'navigation',title:'School sidebar overview',body:'Use Overview for your dashboard and setup. Headteacher contains administrator responsibilities; Teachers contains teaching and class work; Shared contains common academic tools; Smart School Management & Intelligence contains decision-support tools; Integrated School Modules contains connected services; and Info & Session contains help and session links.'},
    {id:'admission',title:'Student Admission & Transfer Management',body:'Use New Student Admission to create learner records, Transfer Admission to process incoming transfers, and Student Search / Profile to locate and maintain learner profiles. These actions preserve the existing permanent student identity and PGSID continuity workflow.',keywords:'admission transfer PGSID GNSIS learner student profile'},
    {id:'getting-started',title:'Getting started',body:'Start with Dashboard, confirm Setup / Config, then use only the modules assigned to your school role. Select a sidebar group to expand it; select an item to open its existing EduTrack page.',keywords:'first login dashboard setup'},
    {id:'dashboard',title:'Dashboard',body:'Purpose: return to the School-Level General Dashboard for available school summaries, alerts, statistics and shortcuts. Who can use it: signed-in School users. Prerequisites: an authenticated School session. Steps: select Dashboard. Save/Generate: this dashboard does not save or generate records. Warning: the summaries shown depend on your permitted school data. Related module: Setup / Config.',keywords:'overview home school general dashboard alerts statistics shortcuts'},
    {id:'language',title:'Switch Language',body:'Purpose: select a supported display language. Who can use it: signed-in School users. Prerequisites: an active School session. Steps: select Switch Language, then choose a supported display language. Save/Generate: the interface selection is applied; it does not alter school data. Warning: changing language never changes student, financial, attendance or result records. Related module: Dashboard.',keywords:'language display translate interface'},
    {id:'setup',title:'Setup / Config',body:'Purpose: maintain permitted school information, academic year, term, classes, subjects, examinations, results, branding and related existing settings. Who can use it: users granted access by existing School permissions. Prerequisites: confirm the correct school and current academic period. Steps: open Setup / Config, review the applicable values, make permitted changes, then use the page save control where provided. Save/Generate: Save stores the configuration used by dependent modules. Warning: incorrect setup can affect dependent modules, including subjects, examinations and results. Related modules: Subject Config and Dashboard.',keywords:'config configuration school year term classes subjects examination results branding save'},
    {id:'subjects',title:'Subject Config',body:'Purpose: review and configure subjects for the relevant level or class. Who can use it: authorized School administrators. Prerequisites: correct academic setup and the intended level/class. Steps: open Subject Config, select the level/class, review or configure subjects, verify the selection, then Save. Save/Generate: Save retains the subject configuration for the selected scope. Warning: correct subject configuration is required before score entry. Related modules: Setup / Config and Score Entry.',keywords:'subject configure level class score entry save'},
    {id:'reports',title:'Reports',body:'Purpose: group School Report Generator and Academic Year Report. Who can use it: School users who can see this Headteacher group. Prerequisites: the selected academic period and report scope. Steps: expand Reports and choose the required report. Generate: generates the selected existing report view for review and any supported print/export action. Warning: review filters before generating. Related modules: Setup / Config and Academic Year Report.',keywords:'reports school report academic year generate print export'},
    {id:'school-report',title:'School Report Generator',body:'Purpose: generate the existing school report for a chosen scope. Who can use it: authorized School users with the visible Reports option. Prerequisites: academic year, term and class/scope are configured. Steps: select academic year, term, class/scope and required filters; Generate; review; then print or export where the existing page supports it. Save/Generate: Generate prepares the report; it does not change records. Warning: verify the scope and filters before sharing a report. Related modules: Academic Year Report and Setup / Config.',keywords:'school report generator year term class filters generate review print export'},
    {id:'academic-year-report',title:'Academic Year Report',body:'Purpose: generate the existing academic-year report. Who can use it: authorized School users with the visible Reports option. Prerequisites: the relevant academic year and applicable filters. Steps: select academic year, select filters, Generate, review, then print or export where supported. Save/Generate: Generate prepares the report without changing source records. Warning: confirm the year and filters before relying on the output. Related modules: School Report Generator and Setup / Config.',keywords:'academic year report filters generate review print export'},
    {id:'fee-hub',title:'Fee Hub',body:'Purpose: provide existing Financial Management System tools: FMS Dashboard, Fee Setup, Class Structures, Record Payment, Receipt Registry, Outstanding Fees and Financial Reports. Who can use it: only users who retain existing Fee Hub RBAC, private-school, school-type and subscription access. Prerequisites: an eligible School and authorized finance access. Steps: expand Fee Hub and choose the appropriate existing tool. Save/Generate: each tool uses its own existing save or report action. Warning: do not bypass existing payment, subscription or school-type restrictions. Related modules: Student Search / Profile and Financial Reports.',keywords:'fees finance FMS payment receipt outstanding'},
    {id:'fms-dashboard',title:'FMS Dashboard',body:'Purpose: view existing finance/payment indicators and quick actions. Who can use it: eligible Fee Hub users. Prerequisites: Fee Hub access. Steps: open FMS Dashboard and review the available indicators. Save/Generate: viewing does not save records. Warning: figures are limited to authorized school data. Related module: Financial Reports.',keywords:'fms dashboard finance payment indicators'},
    {id:'fee-setup',title:'Fee Setup',body:'Purpose: create and manage existing fee types, amounts and categories. Who can use it: eligible Fee Hub users. Prerequisites: Fee Hub access and the intended academic/term setup. Steps: open Fee Setup, review the fee type and amount, complete permitted fields, then Save using the existing page control. Save/Generate: Save updates the configured fee definition. Warning: confirm the amount and category before saving because payment and outstanding-fee views depend on them. Related module: Class Structures.',keywords:'fee setup fee type amount category save'},
    {id:'class-structures',title:'Class Structures',body:'Purpose: assign existing fee types to classes and terms. Who can use it: eligible Fee Hub users. Prerequisites: Fee Setup entries and the correct class/term. Steps: open Class Structures, select class and term, assign the applicable fee types, then Save where supported. Save/Generate: Save retains the fee structure. Warning: verify the class and term before saving. Related modules: Fee Setup and Record Payment.',keywords:'class structures fee assign class term save'},
    {id:'record-payment',title:'Record Payment',body:'Purpose: record an existing student fee payment with receipt tracking. Who can use it: eligible Fee Hub users. Prerequisites: correct student, fee setup and payment access. Steps: search student; verify the name and PGSID; verify the fee; enter amount; choose payment method if the existing page provides it; review; Save; then use the receipt produced by the existing workflow. Save/Generate: Save records the payment and supports existing receipt generation/tracking. Warning: never record money against the wrong student. Related modules: Receipt Registry and Outstanding Fees.',keywords:'record payment student PGSID fee amount payment method receipt save'},
    {id:'receipt-registry',title:'Receipt Registry',body:'Purpose: view and search existing payment receipts, including available date, class and student filters. Who can use it: eligible Fee Hub users. Prerequisites: Fee Hub access. Steps: open Receipt Registry, apply available filters, review the matching receipts, and use existing receipt actions where supported. Save/Generate: searching does not change receipts. Warning: confirm the student and receipt details before using a record. Related module: Record Payment.',keywords:'receipt registry payment receipt date class student search'},
    {id:'outstanding-fees',title:'Outstanding Fees',body:'Purpose: track existing outstanding fee balances. Who can use it: eligible Fee Hub users. Prerequisites: Fee Hub access and accurate fee/payment records. Steps: open Outstanding Fees, apply available filters, review balances and use the existing recovery workflow where permitted. Save/Generate: reviewing does not change balances. Warning: verify payment records before acting on an outstanding balance. Related modules: Record Payment and Financial Reports.',keywords:'outstanding unpaid balance fees student'},
    {id:'financial-reports',title:'Financial Reports',body:'Purpose: review existing financial reports, including the periods supported by the page. Who can use it: eligible Fee Hub users. Prerequisites: Fee Hub access and correct payment data. Steps: open Financial Reports, choose the available period/filters, Generate where provided, review, then print/export where supported. Save/Generate: Generate prepares a report without changing transactions. Warning: validate the selected period and filters. Related modules: FMS Dashboard and Outstanding Fees.',keywords:'financial reports daily weekly monthly term generate print export'},
    {id:'teachers-register',title:'Teachers Register',body:'Purpose: group teacher attendance, setup, term configuration, reporting, analytics, notifications and alerts. Who can use it: School users who can see this Headteacher group. Prerequisites: correct teacher and term records. Steps: Teachers Register → Attendance Register → record/review attendance → Save → Attendance Report → Analytics Dashboard → Notifications/Alerts. Save/Generate: Save retains attendance; report/analytics views summarize existing records. Warning: alerts follow existing escalation logic and do not change it. Related modules: Teacher Setup and Term Config.',keywords:'teachers register attendance save report analytics notifications alerts SISO HR'},
    {id:'attendance-register',title:'Attendance Register',body:'Purpose: record and review existing teacher attendance. Who can use it: authorized School users. Prerequisites: teacher and term setup. Steps: open Attendance Register, record or review the available attendance statuses, then Save using the page control. Save/Generate: Save retains attendance for subsequent reports and alerts. Warning: review dates and teacher identity before saving. Related modules: Attendance Report and Analytics Dashboard.',keywords:'teacher attendance register record review save'},
    {id:'teacher-setup',title:'Teacher Setup',body:'Purpose: maintain the existing teacher setup records used by attendance and related school workflows. Who can use it: authorized School users. Prerequisites: authority to manage teacher data. Steps: open Teacher Setup, review the intended teacher record, complete permitted fields, then Save where provided. Save/Generate: Save updates the existing teacher setup record. Warning: verify the teacher before changing setup. Related modules: Attendance Register and Term Config.',keywords:'teacher setup staff save attendance'},
    {id:'term-config',title:'Term Config',body:'Purpose: configure the existing term context used by teacher attendance workflows. Who can use it: authorized School users. Prerequisites: current academic year and term. Steps: open Term Config, review the term values, update permitted fields, then Save where provided. Save/Generate: Save retains the term configuration. Warning: incorrect term selection affects attendance reporting. Related modules: Attendance Register and Attendance Report.',keywords:'term config academic year attendance save'},
    {id:'attendance-report',title:'Attendance Report',body:'Purpose: review the existing teacher attendance report. Who can use it: authorized School users. Prerequisites: saved teacher attendance. Steps: open Attendance Report, select available filters, Generate where provided, review, then print/export where supported. Save/Generate: Generate prepares a view and does not change attendance. Warning: confirm the reporting period. Related modules: Attendance Register and Analytics Dashboard.',keywords:'teacher attendance report generate review print export'},
    {id:'analytics-dashboard',title:'Analytics Dashboard',body:'Purpose: review existing teacher-attendance analytics. Who can use it: authorized School users. Prerequisites: saved attendance data. Steps: open Analytics Dashboard, apply available filters and review trends. Save/Generate: analytics does not alter attendance. Warning: analytics reflects the available authorized data. Related modules: Attendance Report and Notifications Log.',keywords:'teacher attendance analytics dashboard trends'},
    {id:'notifications-log',title:'Notifications Log',body:'Purpose: review existing teacher-attendance notifications. Who can use it: authorized School users. Prerequisites: recorded attendance and applicable existing notification conditions. Steps: open Notifications Log and review the available entries. Save/Generate: reviewing does not create or alter notifications. Warning: use the log as a record of the existing workflow. Related modules: Analytics Dashboard and Teacher Alert (5-Day / SISO).',keywords:'teacher attendance notifications log'},
    {id:'teacher-alert-5-day',title:'Teacher Alert (5-Day / SISO)',body:'Purpose: review the existing five-day teacher-attendance alert for School Improvement Support Officer escalation. Who can use it: authorized School users. Prerequisites: attendance records that meet the existing alert condition. Steps: open the alert page and review qualifying entries. Save/Generate: this view does not change escalation logic. Warning: do not treat this guide as a change to the existing SISO escalation rules. Related modules: Notifications Log and Attendance Report.',keywords:'teacher alert 5 day SISO absence'},
    {id:'teacher-alert-month',title:'Teacher Critical Alert (1-Month / HR)',body:'Purpose: review the existing one-month critical teacher-attendance alert for HR escalation. Who can use it: authorized School users. Prerequisites: attendance records that meet the existing alert condition. Steps: open the alert page and review qualifying entries. Save/Generate: this view does not change existing HR escalation logic. Warning: use the existing process for any follow-up. Related modules: Notifications Log and Attendance Report.',keywords:'teacher critical alert 1 month HR absence'},
    {id:'integrity',title:'Integrity Check',access:'Integrity Check',body:'Purpose: review the existing System Integrity Dashboard, which checks school name, school number, district, academic year, category/organizer, term and scoring format configuration. Who can use it: School users who can see System Tools. Prerequisites: an authenticated School session. Steps: open Integrity Check, review each reported status and actual value, then use Setup / Config to correct permitted missing or misconfigured values. Save/Generate: the check runs automatically; it does not alter data. Warning: never attempt direct database manipulation to resolve a flag. Related module: Setup / Config.',keywords:'integrity check consistency validation system tools configuration'},
    {id:'sync',title:'Cloud Sync',access:'Cloud Sync',body:'Purpose: review the existing cloud-sync status and record queue. Who can use it: School users who can see System Tools and are authorized by the existing workflow. Prerequisites: configured school details and, for a cloud push, the existing endpoint/token and network availability. Steps: open Cloud Sync, review status, initiate the permitted sync action, then monitor the displayed result. Save/Generate: the current workflow records local status and queues records when the cloud endpoint is unreachable; it reports that an internet connection is needed to push them. Warning: only use a manual School Sync where the existing page authorizes it. Related modules: Integrity Check and Setup / Config.',keywords:'cloud sync school sync sync status queue offline'},
    {id:'user-management',title:'User Accounts & Access Control',access:'User Accounts & Access Control',body:'Purpose: use the existing School-level account/access-control area for permitted user visibility, approved user additions where supported, activation/deactivation, roles/status and permitted edits. Who can use it: only School users with the existing access-control permission. Prerequisites: an authenticated School session and the required authorization. Steps: open User Accounts & Access Control, locate the user, review their status and permitted fields, then apply only the action available to your role. Save/Generate: existing controls persist authorized changes. Warning: visibility does not grant authorization; School-level user management cannot grant District, Regional or National access. Related modules: Staff Registry and Assign Roles.',keywords:'user management accounts access control activate deactivate status permissions'},
    {id:'staff-registry',title:'Staff Registry',access:'Staff Registry',body:'Purpose: use the existing authenticated School staff-management workflow for staff directory records, profiles, employment/active status, class responsibility and School roles. Who can use it: School users who can see Staff Management. Prerequisites: the intended staff member and correct School context. Steps: open Staff Registry, review the authenticated school, register approved staff where supported, maintain permitted profile/employment fields, and use the existing remove/status controls only when authorized. Save/Generate: Save retains the permitted staff record; removed staff remain historical and are excluded from active login, class and role lists. Warning: do not use it to create higher-administration access. Related modules: Assign Class to Teachers and Assign Roles.',keywords:'staff registry staff directory profile employment status responsibility school staff'},
    {id:'assign-class',title:'Assign Class to Teachers',access:'Assign Class to Teachers',body:'Purpose: assign an existing teacher to an existing class for the academic year. Who can use it: authorized School users with Staff Management. Prerequisites: the teacher must be in Teacher Setup/active staff roster, and the correct class/year must be available. Steps: select Teacher → select class → verify Staff ID, class and academic year → Save/Assign. Save/Generate: Assign stores the existing class assignment. Warning: check the teacher and class before saving. Related modules: Teacher Setup and Reassign Class.',keywords:'assign class teacher staff id academic year save'},
    {id:'reassign-class',title:'Reassign Class',access:'Reassign Class',body:'Purpose: transfer an existing class assignment to a replacement teacher. Who can use it: authorized School users with Staff Management. Prerequisites: a current class assignment and an active replacement teacher. Steps: select current assignment/class → select replacement teacher → verify academic year and both teachers → confirm Transfer Assignment. Save/Generate: the existing workflow changes class authority; existing student results, scores and records remain unchanged. Warning: the prior teacher loses publishing authority for that class and the replacement gains it. Related modules: Assign Class to Teachers and Publish Results.',keywords:'reassign class current teacher replacement teacher transfer assignment'},
    {id:'assign-roles',title:'Assign Roles',access:'Assign Roles',body:'Purpose: assign or remove existing School roles for eligible teachers/staff. Who can use it: authorized School users with Staff Management. Prerequisites: an active teacher in the roster and an existing School role. Steps: select teacher → select the least-privilege role needed → verify → Assign Role; use the existing remove action only when appropriate. Save/Generate: Assign Role records the existing role assignment. Warning: avoid unnecessary elevated permissions and never use School roles to grant District, Regional or National access. Related modules: User Accounts & Access Control and Staff Registry.',keywords:'assign roles least privilege role status remove'},
    {id:'publish-results',title:'Publish Results',access:'Publish Results',body:'Purpose: publish existing generated results for the selected period/class when authorized. Who can use it: users allowed by the existing publication workflow; teachers require their assigned class. Prerequisites: academic year, term, class assignment where applicable, generated results and authorization. Steps: verify academic year → term → class → score completeness → calculations → result preview → authorization → Publish. Save/Generate: Publish changes result visibility according to the existing workflow. Warning: review the selected class and period before publishing. Related modules: Score Entry, Block Result and Result Slip.',keywords:'publish results year term class score completeness calculations preview authorization'},
    {id:'block-results',title:'Block Result',access:'Block Result',body:'Purpose: block or restore result visibility using the existing result-control workflow. Who can use it: authorized School users. Prerequisites: the correct result period/class and authorization. Steps: open Block Result, retrieve the applicable result scope, review status, then use the existing block/unblock control. Save/Generate: the action changes visibility according to existing behavior. Warning: blocking does not delete underlying scores. Related modules: Publish Results and Result Slip.',keywords:'block result unblock visibility scores'},
    {id:'publish-mock-results',title:'Publish Mock Results',access:'Publish Mock Results',body:'Purpose: publish an existing mock examination when authorized. Who can use it: the roles permitted by the existing mock-result workflow; teachers require an active class assignment. Prerequisites: a selected mock examination and complete available scores. Steps: verify academic year, term/class context, score completeness, calculations and preview; then Publish. Save/Generate: Publish changes existing mock-result visibility. Warning: verify scope before publication. Related modules: Mock Entry and Block Mock Result.',keywords:'publish mock results mock exam class scores'},
    {id:'block-mock-results',title:'Block Mock Result',access:'Block Mock Result',body:'Purpose: block or restore visibility of existing mock results. Who can use it: authorized School users. Prerequisites: the correct mock result scope and authorization. Steps: retrieve the mock result, review current status, then use the existing block/unblock action. Save/Generate: this controls visibility; it does not delete underlying mock scores. Warning: confirm examination and class before acting. Related modules: Publish Mock Results and Mock Result.',keywords:'block mock result unblock visibility mock scores'},
    {id:'new-admission',title:'New Student Admission',access:'New Student Admission',body:'Purpose: register a brand-new learner using the existing School admission workflow. Who can use it: authorized School users with this visible option. Prerequisites: correct school/class context and required learner/guardian/admission details. Steps: open module → enter required learner details → guardian details → class/admission information → validate → submit → confirm the permanent Student ID/PGSID where generated → review profile. Save/Generate: Submit creates the existing admission/profile record according to the workflow. Warning: search first when identity is uncertain; do not create a new permanent identity for promotion, repetition or transfer. Related modules: Transfer Admission and Student Search / Profile.',keywords:'GNSIS admission new student PGSID permanent student ID guardian class'},
    {id:'transfer-admission',title:'Transfer Admission',access:'Transfer Admission',body:'Purpose: process an incoming learner through the existing transfer workflow. Who can use it: authorized School users with this visible option. Prerequisites: the learner identity/PGSID and valid receiving-school context. Steps: search for the existing learner/PGSID → verify identity → process the transfer through the existing workflow → retain the permanent identity. Save/Generate: the existing workflow records the transfer/enrollment change. Warning: a learner must not receive a new permanent identity merely because of promotion, repetition or transfer; search for the existing record first. Related modules: New Student Admission and Student Search / Profile.',keywords:'GNSIS transfer PGSID existing learner permanent identity'},
    {id:'student-search',title:'Student Search / Profile',access:'Student Search / Profile',body:'Purpose: locate the existing student identity/profile through the School search workflow. Who can use it: authorized School users with this visible option. Prerequisites: a known PGSID, name or class where those existing search fields are available. Steps: open Student Search / Profile, search using the supported identifier, verify the learner identity, then review the existing profile. Save/Generate: searching does not create a learner identity. Warning: use this search before admission or transfer whenever identity is uncertain. Related modules: New Student Admission and Transfer Admission.',keywords:'GNSIS admission transfer PGSID student search profile name class'},
    {id:'score-entry',title:'Score Entry',access:'Score Entry',body:'Purpose: enter existing assessment scores for an authorized class and subject. Who can use it: teachers only for authorized classes/subjects and other users permitted by existing School controls. Prerequisites: academic year, term, class, subject and assessment format. Steps: Academic Year → Term → Class → Subject → assessment format → enter scores → review totals/calculations → Save Scores → confirm persistence. Save/Generate: Save Scores persists the entered scores for the selected scope. Warning: verify the class, subject and permanent student identity before saving. Related modules: Subject Config, Multi-Subject Entry and Publish Results.',keywords:'score entry assessment format save scores totals calculations subject class term'},
    {id:'multi-subject',title:'Multi-Subject Entry',access:'Multi-Subject Entry',body:'Purpose: use the existing consolidated teacher score-entry interface across subjects. Who can use it: teachers with authorized class/subject access and other permitted School users. Prerequisites: select Class, Term and Subject. Steps: select the active class, term and subject; enter scores for the displayed students; review the active subject and format; then use Save Subject Scores. The existing interface allows switching subjects without data loss and includes Sync to Result Engine. Save/Generate: Save Subject Scores persists that subject; Sync uses the existing result-engine integration. Warning: confirm the active subject before saving. Related modules: Score Entry and Subject Config.',keywords:'multi subject consolidated active subject save subject scores sync result engine'},
    {id:'mock-entry',title:'Mock Entry',access:'Mock Entry',body:'Purpose: enter existing mock examination scores. Who can use it: authorized School users for their permitted class/subject scope. Prerequisites: mock examination, class, subject and available students. Steps: select mock examination → class → subject → enter scores → review → Save Mock Scores. Save/Generate: Save Mock Scores persists the current mock sheet. Warning: the existing Clear action removes data from the mock entry sheet; review before using it. Related modules: Publish Mock Results and Mock Result.',keywords:'mock entry mock examination class subject save mock scores'},
    {id:'pupils-register',title:'Pupils Register',access:'Attendance Register',body:'Purpose: group existing pupil attendance, setup, messaging history, reports, audit, automation and critical-alert tools. Who can use it: School users with the visible Teachers/Pupils Register options. Prerequisites: correct class and pupil records. Steps: Pupils Register → Attendance Register → confirm date/class → mark the available Present, Absent, Tardy or Excused status → add required reason/time/details where the existing form requests them → Save → review reports/alerts. Save/Generate: Save retains attendance for the existing reports and alert workflows. Warning: check date and class before saving. Related modules: Pupil Setup and Attendance Reports.',keywords:'pupils register pupil attendance present absent tardy excused save'},
    {id:'pupil-setup',title:'Pupil Setup',access:'Pupil Setup',body:'Purpose: maintain the existing pupil register information for each class, including name, gender, admission number and parent/guardian phone used for SMS notifications. Who can use it: authorized School users. Prerequisites: correct class and pupil details. Steps: open Pupil Setup, select the applicable class, enter or review permitted pupil details, then Save using the existing control. Save/Generate: Save updates the existing pupil setup record. Warning: verify parent/guardian contact details before saving. Related modules: Attendance Register and SMS Logs.',keywords:'pupil setup class name gender admission number guardian phone SMS'},
    {id:'sms-logs',title:'SMS Logs',access:'SMS Logs',body:'Purpose: review the existing SMS Logs & History for attendance-related messaging. Who can use it: authorized School users. Prerequisites: attendance/messaging activity where applicable. Steps: open SMS Logs, apply available review filters and inspect message history/status. Save/Generate: reviewing logs does not resend or alter messages. Warning: treat contact and message history as school data. Related modules: Pupil Setup and Attendance Register.',keywords:'SMS logs history attendance messaging'},
    {id:'pupils-report',title:'Pupils Report',access:'Pupils Report',body:'Purpose: review the existing Pupils Attendance Report. Who can use it: authorized School users. Prerequisites: saved pupil attendance. Steps: open Pupils Report, choose available class/date filters, generate or review the displayed report, then print/export only where supported. Save/Generate: reporting does not alter attendance records. Warning: validate the reporting scope. Related modules: Attendance Register and Attendance Reports.',keywords:'pupils report pupil attendance report generate'},
    {id:'pupil-audit',title:'Audit Trail',access:'Audit Trail',body:'Purpose: review the existing attendance audit history. Who can use it: authorized School users. Prerequisites: recorded attendance changes. Steps: open Audit Trail and review the logged history for the relevant records. Save/Generate: the audit view is read-only evidence of existing changes. Warning: audit history must not be manipulated. Related modules: Attendance Register and Automation Hub.',keywords:'pupil audit trail attendance history'},
    {id:'attendance-reports',title:'Attendance Reports',access:'Attendance Reports',body:'Purpose: use the existing attendance reporting page. Who can use it: authorized School users. Prerequisites: saved pupil attendance. Steps: open Attendance Reports, select supported filters, generate/review the available report, then use print/export where supported. Save/Generate: reports summarize stored attendance and do not change it. Warning: confirm date/class filters. Related modules: Pupils Report and Attendance Register.',keywords:'attendance reports pupil class date generate'},
    {id:'automation-hub',title:'Automation Hub',access:'Automation Hub',body:'Purpose: review existing attendance automation, including duplicate prevention, timestamp capture, SMS/WhatsApp alerts, digital signatures and integration status. Who can use it: authorized School users. Prerequisites: existing attendance records and configured connected services where applicable. Steps: open Automation Hub, review the available automation status/logs, then use only authorized existing controls. Save/Generate: automation follows existing configured processes. Warning: do not bypass audit or duplicate-prevention safeguards. Related modules: Audit Trail and SMS Logs.',keywords:'attendance automation duplicate prevention timestamp WhatsApp SMS signatures'},
    {id:'headteacher-critical-alert',title:'Headteacher Critical Alert (3-Day)',access:'Headteacher Critical Alert (3-Day)',body:'Purpose: review the existing three-day consecutive pupil-absence critical alert for Headteacher attention. Who can use it: authorized School users with this visible option. Prerequisites: attendance records meeting the existing condition. Steps: open the alert page and review qualifying pupil records and available details. Save/Generate: this view does not change existing alert logic. Warning: use the established school follow-up process. Related modules: Attendance Register and Attendance Reports.',keywords:'headteacher critical alert 3 day pupil absence'},
    {id:'shep',title:'SHEP Activities',access:'SHEP Activities',body:'Purpose: manage the existing School Health Education Programme register, including activities, inspections, uploads and reports. Who can use it: authorized School-level users for this school only. Prerequisites: correct activity details and any permitted supporting evidence. Steps: open SHEP Activities, select the relevant activity area, enter permitted activity/participant details, attach/upload only where supported, then Save; use the existing report action to review/print. Save/Generate: Save retains the School SHEP record and existing audit logging. Warning: handle health-related information according to school confidentiality requirements. Related modules: School Dashboard Analytics and Audit Trail.',keywords:'SHEP school health education programme screenings talks campaigns referrals inspections uploads reports'},
    {id:'subject-register',title:'Subject Register',access:'Subject Register',body:'Purpose: manage the existing per-class register of subjects taught this term, including teacher/class/period assignments, availability, workload and history. Who can use it: authorized School-level users. Prerequisites: correct class, subject and teacher context. Steps: open Subject Register, review the current assignment, add or edit permitted subject/class/teacher/period information, then Save using the existing control. Save/Generate: Save retains the register record and audit history. Warning: this differs from Subject Config, which defines the subjects the school offers. Related modules: Subject Config and Timetable AI.',keywords:'subject register class subject teacher period workload history'},
    {id:'sporting',title:'Sporting Activities',access:'Sporting Activities',body:'Purpose: manage the existing School sporting register for sports events, equipment, attendance and achievements across disciplines. Who can use it: authorized School-level users for this school only. Prerequisites: accurate event, participant/team or equipment details as applicable. Steps: open Sporting Activities, select the appropriate activity area, record permitted event/fixture, participation/attendance, equipment or achievement details, then Save; use the existing report action to review/print. Save/Generate: Save retains the School record and existing audit history. Warning: verify participants and event details before saving. Related modules: School Dashboard Analytics and Audit Trail.',keywords:'sporting activities sports events fixtures teams participants equipment attendance achievements competitions report'},
    {id:'lms',title:'Learning Management (LMS)',access:'Learning Management (LMS)',body:'Purpose: use the existing teacher LMS for lessons, assignments/homework, quizzes, discussion and learning resources. Who can use it: authorized School teachers/staff with access to the visible LMS. Prerequisites: correct class and subject context. Steps: open Learning Management (LMS), choose the relevant teacher area, create or review permitted lessons, assignments, quizzes, discussion items or resources, then Save/Publish through the existing controls. Save/Generate: saved items synchronize to the existing student-facing LMS; quizzes use the existing auto-marking workflow where applicable. Warning: publish only material intended for the selected class. Related modules: Quiz and Student portal learning views.',keywords:'LMS lessons assignments homework quizzes discussion resources learning materials auto marking'},
    {id:'student-database',title:'Student Database',access:'Student Database',body:'Purpose: search and view students belonging to the authenticated school. Who can use it: School users with the visible Shared option. Prerequisites: an authenticated School session. Steps: open Student Database and use the existing Smart Search controls, including student/index or admission identifier, partial student name and available class filters; select the matching record to view its profile. Save/Generate: searching and viewing do not change student records. Warning: school-data isolation applies—do not use the module to access another school’s students. Related modules: Student Search / Profile and Result Slip.',keywords:'student database student search index admission number name class profile authenticated school isolation'},
    {id:'result-slip',title:'Result Slip',access:'Result Slip',body:'Purpose: generate and print existing individual result slips. Who can use it: authorized School users. Prerequisites: academic year, term, class and selected student or existing bulk option; generated/published result availability follows the existing result-publication logic. Steps: Academic Year → Term → Class → student/bulk option → Generate → Preview → verify → Print/Export where supported. Save/Generate: Generate prepares the existing slip; preview and print/export do not alter scores. Warning: preview before printing and confirm the learner, class and period. Related modules: Broadsheet, Publish Results and Student Database.',keywords:'result slip academic year term class student bulk generate preview print export published'},
    {id:'mock-result',title:'Mock Result',access:'Mock Result',body:'Purpose: generate or view existing mock examination result slips/results. Who can use it: authorized School users. Prerequisites: saved mock scores and the correct mock/class context. Steps: open Mock Result, select the available examination/class/student scope, generate or view the existing result, then review or print where supported. Save/Generate: Generate/view does not change mock scores. Warning: mock visibility remains governed by the existing mock-publication controls. Related modules: Mock Entry, Mock Exam Analysis and Publish Mock Results.',keywords:'mock result mock exam slip generate view print'},
    {id:'mock-analysis',title:'Mock Exam Analysis',access:'Mock Exam Analysis',body:'Purpose: review the existing mock subject, student and class performance analysis. Who can use it: authorized School users. Prerequisites: saved mock results and an available examination/class scope. Steps: open Mock Exam Analysis, apply the existing examination, class, subject or student filters, then review the available performance analysis. Save/Generate: analysis does not change scores. Warning: use results with teacher review and the wider academic context. Related modules: Mock Result and Mock Entry.',keywords:'mock exam analysis subject student class performance filters'},
    {id:'broadsheet',title:'Broadsheet',access:'Broadsheet',body:'Purpose: view the existing consolidated class results/broadsheet. Who can use it: authorized School users. Prerequisites: correct academic year, term/exam, class and available scores. Steps: Academic Year → Term/exam → Class → Generate/Open → review consolidated results. Save/Generate: Generate/Open prepares the existing view and does not change scores. Warning: inspect missing or incorrect scores before relying on the consolidated result. Related modules: Score Entry, Rankings and Result Slip.',keywords:'broadsheet academic year term exam class generate consolidated results'},
    {id:'rankings',title:'Rankings',access:'Rankings',body:'Purpose: review existing class and school rankings by aggregate. Who can use it: authorized School users. Prerequisites: complete results for the selected scope. Steps: open Rankings, select the available class/period scope and review the generated ranking list. Save/Generate: reviewing rankings does not change calculations. Warning: interpret rankings with broader academic information, not as the sole measure of a learner. Related modules: Broadsheet and Chart Analysis.',keywords:'rankings class school aggregate performance'},
    {id:'chart-analysis',title:'Chart Analysis',access:'Chart Analysis',body:'Purpose: review the existing graphical performance analysis and comparisons. Who can use it: authorized School users. Prerequisites: results for the selected scope. Steps: open Chart Analysis, apply available class, subject, period or comparison filters, then review charts and comparisons. Save/Generate: analysis does not alter source results. Warning: validate the selected filters before interpreting a chart. Related modules: Rankings, Broadsheet and Mock Exam Analysis.',keywords:'chart analysis graphs performance filters comparisons class subject'},
    {id:'index-generator',title:'Index Generator',access:'Index Generator',body:'Purpose: review/generate existing examination or student index numbers by class/form rules. Who can use it: authorized School users when the visible Index Generator is available. Prerequisites: valid school number, class/form and existing index configuration; JHS/WAEC cases retain their existing validation/manual requirements. Steps: open Index Generator, review the class/form code and generated/required index values, validate the scope, then use the existing generation/entry action where supported. Save/Generate: generation follows the existing index rules. Warning: do not substitute an index number for a permanent student identity. Related modules: Setup / Config and Student Database.',keywords:'index generator examination student index class form validation school number WAEC'},
    {id:'result-processing',title:'Result Processing Workflow',body:'Purpose: provide a safe guide through the existing result process. Who can use it: School users only for modules they are authorized to access. Steps: Setup/Config → Subject Config → Teacher/Class Assignment → Score Entry → verify missing/incorrect scores → Broadsheet → Rankings/Chart Analysis where required → Result Slip → Preview → correction if required → Publish Results → verify authorized Parent/Student visibility. Save/Generate: each existing module retains its own save/generate action. Warning: this guide does not change formats, calculations, PGSID, data records or result-publication rules. Related modules: all Shared result tools.',keywords:'result processing workflow score entry broadsheet rankings chart result slip preview publish parent student'},
    {id:'mock-workflow',title:'Mock Results Workflow',body:'Purpose: guide existing mock result processing. Who can use it: School users only for modules they are authorized to access. Steps: Mock Entry → Mock Result → Mock Exam Analysis → review/correct → Publish Mock Results. Save/Generate: each stage retains its existing controls and publication rules. Warning: correct mock scores in the proper entry workflow before publishing; this guide does not alter mock calculations or records. Related modules: Mock Entry, Mock Result and Mock Exam Analysis.',keywords:'mock workflow mock entry mock result analysis review correct publish'},
    {id:'ai-analytics',title:'AI Analytics Engine',access:'AI Analytics Engine',body:'Purpose: review the existing School predictive dashboard for dropout and failure risk, teacher and pupil absenteeism, budget, infrastructure, teacher requirements, performance trend, population projection and generated recommendations. Who can use it: School users with the visible module. Prerequisites: the available school records that feed the displayed indicators. Steps: open AI Analytics Engine, review the dashboard cards, charts and recommendation details; where appropriate use Route to Workflow to create the existing workflow request. Save/Generate: opening analysis does not change source records; routing creates an existing workflow request. Warning: AI output supports decision-making only—verify significant conclusions against source records before acting. Related modules: Workflow Automation and Business Intelligence.',keywords:'AI analytics artificial intelligence predictive dropout failure risk absenteeism budget recommendations decision making'},
    {id:'workflow-automation',title:'Workflow Automation',access:'Workflow Automation',body:'Purpose: submit, review and act on the existing digital approval-chain workflow requests. Who can use it: School users with the visible module; approve, return or reject actions appear only at the user’s current workflow stage. Prerequisites: a valid request type, concise description and justification. Steps: select Request Type → enter Description and Reason / Justification → Submit Request → review the request status, stage track and audit details → use the available Approve, Return or Reject control with a comment when authorized. Save/Generate: Submit creates a request; an action updates it through the existing approval chain. Warning: review the request conditions, justification and current stage before submitting or acting; this page does not provide a separate automation-rule activation control. Related modules: AI Analytics Engine and Procurement.',keywords:'automation workflow approval request activate activation review approve return reject conditions audit'},
    {id:'business-intelligence',title:'Business Intelligence',access:'Business Intelligence',body:'Purpose: review the existing executive dashboard and school management analytics. Who can use it: School users with the visible module. Prerequisites: available School records for the displayed metrics. Steps: open Business Intelligence, review KPI cards, then switch between School Performance, Gender Analysis, Domain Analytics and Regional Map tabs; inspect the available class drill-down, charts, KPI comparisons and current session scope. Save/Generate: dashboard review does not alter source records. Warning: use the displayed operational baselines and scope as context, and verify important decisions against the underlying school records. Related modules: AI Analytics Engine, Library, Student Health and Procurement.',keywords:'business intelligence BI dashboard KPIs analytics performance gender comparisons filters school management'},
    {id:'student-health',title:'Student Health',access:'Student Health',body:'Purpose: maintain the existing School student health record, including vitals, allergies, medical history, emergency contacts, vaccinations, medication history and clinic visits. Who can use it: School users with the visible module and authority to handle the record. Prerequisites: select the correct class and student; obtain/confirm the information through the school’s authorized process. Steps: select Class → select Student → review/update permitted health fields → Save Health Record; use the dedicated add controls for contacts, vaccinations and medication, or Log Clinic Visit & Notify Parent where appropriate. Save/Generate: Save Health Record and the existing add/log controls retain those records; a clinic visit uses the existing parent-notification workflow. Warning: health information is confidential—use only authorized access, disclose only through approved processes, and confirm the learner before saving. Related modules: SHEP Activities and Guidance & Counselling.',keywords:'health student health medical records allergy vaccination immunization medication clinic visits confidential permissions'},
    {id:'library',title:'Library',access:'Library',body:'Purpose: use the existing School library catalog, circulation, reservation, fines and reading analytics tools. Who can use it: School users with the visible module and the required operational authority. Prerequisites: correct book and student records. Steps: use Catalog to add titles/e-books and inventory details; use Issue/Return to select or barcode-scan an available book, select the student and loan period, then Issue Book; use Return when received; review Reservations, Fines and Reading Analytics as needed. Save/Generate: Add Book, Issue Book, Return, Reserve and fine actions update the corresponding existing library records. Warning: verify the book, learner and due date before recording a circulation action. Related modules: Student Database and Business Intelligence.',keywords:'library catalogue catalog inventory books borrowing loan returns borrowers reservations fines reports reading analytics barcode'},
    {id:'timetable-ai',title:'Timetable AI',access:'Timetable AI',body:'Purpose: configure, validate, generate and review the existing School timetable tools. Who can use it: School users with the visible module; archive access retains its existing Headteacher/System Administrator restriction. Prerequisites: confirm classes, subjects, teachers/assignments, teaching mode, school times, periods and breaks for the intended level. Walkthrough: confirm classes → subjects → teachers/assignments → periods/breaks → choose the existing timetable mode/settings → Generate → inspect conflicts or validation messages → make permitted adjustments → confirm/publish or export where the existing page supports it. Save/Generate: configuration save actions retain setup; Generate creates a timetable only when existing validation and clash checks succeed. Warning: review the auto-optimise preview before confirming it, and do not manually assign a teacher where the existing conflict check reports a clash. Related modules: Subject Register and Subject Config.',keywords:'timetable AI timetable generation classes subjects teachers assignments periods breaks conflicts validation publish export'},
    {id:'procurement',title:'Procurement',access:'Procurement',body:'Purpose: use the existing School procurement and inventory workflow. Who can use it: School users with the visible module; each action follows the current approval-stage controls. Prerequisites: accurate item, quantity, estimated cost and justification. Steps: create a purchase request → review approval-chain progress → record quotations when available at the applicable stage → issue the existing purchase order → confirm goods received into store → register the received asset and location → review inventory. Save/Generate: Submit Purchase Request, quotation, purchase-order, receiving and asset-registration actions retain the corresponding existing workflow record. Warning: verify costs, supplier quotation, receipt and asset location before acting; do not bypass required authorization stages. Related modules: Workflow Automation and Business Intelligence.',keywords:'procurement purchase request quotations purchase order receiving inventory assets supplier authorization approval'},
    {id:'guidance-counselling',title:'Guidance & Counselling',access:'Guidance & Counselling',body:'Purpose: maintain the existing confidential student guidance timeline for behaviour, academic concerns, parent meetings, career guidance, interventions, recommendations, actions taken and follow-up. Who can use it: Counsellors, Headteachers and other roles authorized by the existing module; an unauthorized session sees its access restriction. Prerequisites: select the correct student and have an authorized reason to record the entry. Steps: select Student → choose the available entry type and date → enter the confidential note → Add Timeline Entry → review the existing timeline. Save/Generate: Add Timeline Entry saves the confidential record; Parent Meetings use the existing parent-notification workflow. Warning: treat all counselling, referral, activity and follow-up information as confidential and never use the module outside RBAC or the school’s approved support process. Related modules: Student Health and Student Database.',keywords:'guidance counselling counselor student support referral activity follow up confidential RBAC parent meetings'},
    {id:'online-admission',title:'Online Admission',access:'Online Admission',body:'Purpose: start the existing online new- or transfer-admission application workflow. Who can use it: users who can open the visible integration; the application remains subject to server-side validation and School review. Steps: select admission type → region → district → registered school → educational level → class → Continue → enter learner and guardian details, plus transfer details when applicable → confirm accuracy → Submit Admission Application → retain the application reference. Save/Generate: submission creates a pending-review application only; it does not create a permanent Student ID or Index Number. Warning: use Student Admission & Transfer Management and Admissions Review to process accepted applications without duplicating an existing permanent identity. Related modules: Admissions Review, New Student Admission and Transfer Admission.',keywords:'online admission application new transfer learner guardian pending review application reference permanent student ID'},
    {id:'communication-hub',title:'Communication Hub',access:'Communication Hub',body:'Purpose: compose and review the existing school-scoped SMS and email campaigns. Who can use it: School users authorized by the communication service and any existing school-type/subscription rules. Prerequisites: authorized audience, correct class ID when targeting a class, and a complete message; email may include a subject. Steps: choose SMS or Email → name the campaign if needed → select audience → enter a class ID where requested → write and preview the message → refresh recipient count → Send now or choose a schedule → review Campaign History and any delivery report. Save/Generate: send/schedule creates the existing campaign record. Warning: push notifications remain unavailable until device infrastructure is configured; verify recipients and applicable subscription/school-type access before sending. Related modules: Chat and SMS Logs.',keywords:'communication hub SMS email notification campaign audience recipients schedule delivery history subscription school type'},
    {id:'chat',title:'Chat',access:'Chat',body:'Purpose: use the existing direct, relationship-scoped School chat. Who can use it: authenticated users who appear in the authorized contact list. Prerequisites: an authorized contact and active School session. Steps: open Chat → search authorized contacts → select a contact → review the private conversation → write a message → Send. Save/Generate: Send records the message through the existing chat service; the conversation refreshes for new messages. Warning: contacts and conversations are permission-scoped; use professional, confidential communication and do not share student, health, result or access information beyond authorized recipients. Related modules: Communication Hub and Guidance & Counselling.',keywords:'chat direct message authorized contacts conversation confidential school communication'},
    {id:'control-panel',title:'Control Panel',access:'Control Panel',body:'Purpose: open the existing Control Panel integration, whose server authorization determines whether the current session can view its aggregate, search, export, drill-down or branding controls. Who can use it: only sessions granted the integration’s existing authorization; a School user must not treat it as a District, Regional or National control function. Prerequisites: an authorized session and the permitted scope returned by the server. Steps: open Control Panel, use only the filters and school drill-down records the service exposes, refresh or export where authorized, and save branding only where that action is permitted. Save/Generate: Refresh reads authorized aggregates; Export CSV produces the existing authorized export; branding save does not alter RBAC, tenant identity or database identity. Warning: do not attempt to use this integration to broaden school scope or access another school. Related modules: Dashboard and Analytics Narrative.',keywords:'control panel authorized school scope aggregates export CSV branding drill down permissions'},
    {id:'analytics-narrative',title:'Analytics Narrative',access:'Analytics Narrative',body:'Purpose: generate the existing advisory written interpretation from verified authorized School analytics. Who can use it: School users who can open the visible narrative card and its underlying analytics. Prerequisites: the available School/class analytics context. Steps: open Analytics Narrative → select the available class context where applicable → Generate insight → read the narrative together with the displayed verified metrics and unavailable-data notice. Save/Generate: Generate insight requests advisory wording; existing alerts and calculations remain authoritative and are not changed. Warning: verify the source data before acting on the narrative, especially for significant academic or attendance decisions. Related modules: Business Intelligence and Chart Analysis.',keywords:'analytics narrative written interpretation AI insight verified source data school analytics'},
    {id:'quiz',title:'Quiz',access:'Quiz',body:'Purpose: open the existing quiz response interface. Who can use it: the current implementation is a student-learning quiz runner for a quiz ID supplied by the school or teacher; it does not provide School-level quiz creation or assignment controls on this page. Prerequisites: an available quiz ID and permission to access that quiz. Steps: open Quiz → enter the quiz ID → review questions and any time limit → choose each multiple-choice answer or enter a short answer → Submit Quiz → review the saved graded result. Save/Generate: Submit Quiz sends the response and saves the graded attempt to the existing gradebook. Warning: do not imply that opening this School sidebar item creates, assigns or edits a quiz; use the existing authorized LMS tools for those functions where available. Related modules: Learning Management (LMS) and Score Entry.',keywords:'quiz quiz ID questions multiple choice short answer submit response gradebook assignment creation'},
    {id:'admissions-review',title:'Admissions Review',access:'Admissions Review',body:'Purpose: review and progress existing online new and transfer applications for the authenticated school. Who can use it: authorized School users; the API applies existing authentication and school scope. Prerequisites: an application reference or an available application in the current school’s queue. Walkthrough: open application → review learner, guardian, application and transfer information → verify supporting data → Start Review where available → Approve, Request Correction or Reject according to the existing controls → enter a reason/comment when Request Correction or Reject requires it → Save/confirm the action → after approval, use Finalize Admission when authorized. Save/Generate: actions update the existing application history; finalization creates the permanent EduTrack student record. Warning: accepted applications transition into the existing admission/student-record process—search first and do not create a duplicate permanent identity. Related modules: Online Admission and Student Admission & Transfer Management.',keywords:'admissions review online application approve reject correction finalize admission guardian learner transfer permanent identity'},
    {id:'transport-management',title:'Transport Management',access:'Transport Management',body:'Purpose: use the existing School transport registry, student allocation and movement-record tools. Who can use it: authorized School staff; access and any school-type/subscription availability remain governed by the existing service. Prerequisites: correct school/tenant context and valid vehicle, route, stop or student identifiers. Steps: create the permitted Vehicle, Route or Stop record → review registry/KPIs → assign or reassign a student to route, stop and vehicle → record pickup/drop-off event where authorized → review current controlled location and refresh. Save/Generate: create, assignment, event and location actions update the existing scoped transport records; offline movement events are queued for synchronization. Warning: verify the student, route and vehicle before recording movement; do not use transport data outside the authenticated school scope. Related modules: Student Database and QR Attendance.',keywords:'transport management vehicle route driver stop student allocation pickup drop off location offline school type subscription'},
    {id:'hostel-management',title:'Hostel Management',access:'Hostel Management',body:'Purpose: use the existing School boarding-capacity, assignment and roll-call tools. Who can use it: users with the existing hostel permissions; School type, subscription and operational availability remain controlled by the implementation. Prerequisites: correct school/tenant context and registered hostel structure. Steps: create the permitted Hostel, Block, Room or Bed structure → review occupancy KPIs → assign or reassign the student to hostel/block/room/bed → record the applicable Morning, Evening or Night roll call as Present, Absent or Excused → refresh and review records. Save/Generate: structure, assignment and roll-call controls update the existing hostel records; offline roll calls queue for synchronization. Warning: verify capacity, bed and learner before saving, and use Fee Hub only through its existing eligible access for hostel fees. Related modules: Student Database and Fee Hub.',keywords:'hostel management boarding hostel block room bed occupancy student assignment roll call permissions school type subscription'},
    {id:'qr-attendance',title:'QR Attendance',access:'QR Attendance',body:'Purpose: use the existing secure camera or token-based attendance workflow connected to the established registers. Who can use it: authorized attendance managers; QR identity rotation retains its existing authorization. Prerequisites: active School session, correct existing student/staff record, and camera permission or an authorized token fallback. Walkthrough: open QR Attendance → Start camera or use the authorized token → scan/enter the code → verify the returned person/record and attendance date → confirm the recorded status → Save where the existing workflow records it. Save/Generate: a valid scan records attendance, suppresses rapid duplicates and can queue offline scans for automatic synchronization; Generate/regenerate rotates an existing student or staff QR identity and disables the previous code. Warning: never scan for another school or create a QR identity without verifying the existing record. Related modules: Attendance Register and Transport Management.',keywords:'QR attendance scan camera token verify person record attendance save offline synchronization QR identity'},
    {id:'access-status',title:'Access, validation and status messages',body:'Purpose: explain real system messages without bypassing existing controls. Access Denied or Restricted Feature means the current role, school type, subscription or permission does not allow the action; use an authorized School process rather than seeking a workaround. Validation Error means required or inconsistent information needs correction before Save, Submit, Generate or Publish. Save Successful confirms the existing record action completed. Pending Synchronization means an existing offline queue will retry when connectivity returns; Synchronized confirms that queue completed. Published and Blocked describe existing result-visibility status, not score deletion. Payment Successful or Failed reflects the existing payment workflow—verify the student, amount and receipt/status before retrying or following up.',keywords:'access denied restricted feature validation error save successful pending synchronization synchronized published blocked payment successful failed'},
    {id:'common-workflows',title:'Common Workflows',body:'Purpose: provide safe daily routes through existing School functions. Follow only modules visible to your role and confirm each page’s current school, academic year, term, class and identity context before acting. Related modules: Dashboard, attendance, admissions, results, Fee Hub and System Tools.',keywords:'common workflows daily teacher headteacher admission fee attendance safety'},
    {id:'teacher-daily-workflow',title:'Teacher Daily Workflow',body:'Login → Dashboard → review notifications → Pupils Register / Attendance → teaching, Learning Management (LMS) or Subject Register → Score Entry when required → verify saves → review alerts/tasks → Log Out. Who can use it: School teachers and staff only for visible authorized modules. Warning: confirm date, class, subject and learner identity before attendance or score save; do not enter scores outside your authorized class/subject assignment. Related modules: Attendance Register, LMS, Subject Register and Score Entry.',keywords:'teacher daily workflow login dashboard notifications pupil attendance LMS subject register score entry alerts log out'},
    {id:'headteacher-daily-workflow',title:'Headteacher Daily Workflow',body:'Login → Dashboard → pupil attendance → teacher attendance → alerts → admissions → score completion → reports/analytics → authorized users, staff, classes and roles → result review/publication → finance where authorized → Cloud Sync / Integrity Check → Log Out. Who can use it: Headteachers and School administrators with the corresponding visible permissions. Warning: review scope, authorization and underlying data at every decision point; Fee Hub and elevated staff controls retain existing school-type, subscription and RBAC restrictions. Related modules: Teachers Register, Student Admission & Transfer Management, Reports, Fee Hub and System Tools.',keywords:'headteacher daily workflow pupil teacher attendance alerts admissions reports analytics users staff classes roles results finance sync integrity log out'},
    {id:'admission-workflow',title:'Admission Workflow',body:'Online Admission / Admissions Review where applicable → Student Admission & Transfer Management → New Student Admission or Transfer Admission → identity verification → PGSID/permanent identity → class placement → Student Search / Profile. Who can use it: authorized School users. Save/Generate: online applications remain pending until the existing review/finalization process; admission/transfer uses the established record workflow. Warning: search for the learner first and never create another permanent identity merely for transfer, promotion or repetition. Related modules: Online Admission, Admissions Review and Student Search / Profile.',keywords:'admission workflow online admission admissions review transfer PGSID permanent identity class placement student search'},
    {id:'fee-workflow',title:'Fee Workflow',body:'Fee Setup → Class Structures → Record Payment → Receipt Registry → Outstanding Fees → Financial Reports. Who can use it: only users retaining existing Fee Hub authorization, school-type and subscription eligibility. Before payment, verify authenticated school, student name, PGSID, fee, amount and payment status. Save/Generate: Record Payment uses the existing receipt workflow; report actions do not change transactions. Warning: never record money against the wrong student or retry a failed payment without checking its existing status/receipt. Related modules: Student Search / Profile and FMS Dashboard.',keywords:'fee workflow fee setup class structures record payment receipt registry outstanding fees financial reports payment successful failed'},
    {id:'pupil-attendance-workflow',title:'Pupil Attendance Workflow',body:'Pupils Register → Attendance Register → confirm date/class → mark the existing attendance status → add required reason/time/details → Save → review Pupils Report, Attendance Reports, Audit Trail, Automation Hub and Headteacher Critical Alert (3-Day). Who can use it: authorized School users. Warning: verify the class, date and pupil identity before saving; do not manipulate audit history or bypass existing alert logic. Related modules: Pupil Setup and SMS Logs.',keywords:'pupil attendance workflow register present absent tardy excused reports audit automation headteacher 3 day alert'},
    {id:'teacher-attendance-workflow',title:'Teacher Attendance Workflow',body:'Teachers Register → Attendance Register → record/review attendance → Save → Attendance Report → Analytics Dashboard → Notifications Log → Teacher Alert (5-Day / SISO) and Teacher Critical Alert (1-Month / HR). Who can use it: authorized School users. Warning: verify the teacher, date and term before saving; reports and alerts follow existing escalation logic. Related modules: Teacher Setup and Term Config.',keywords:'teacher attendance workflow register report analytics notifications SISO HR 5 day 1 month alert'},
    {id:'security-accuracy',title:'Security & Data Accuracy',body:'Before Save, Submit, Publish, Block, Approve, Assign, Reassign or Payment, verify the authenticated school, academic year, term, class, student/staff identity, PGSID where relevant, amount/scores/status and your authorization. Never share credentials; protect confidential health, counselling, financial and learner records; never bypass RBAC or manipulate protected routes; and always log out from a shared device. If access is restricted, use the approved School process rather than seeking a workaround. Related modules: User Accounts & Access Control, Cloud Sync and Log Out.',keywords:'security data accuracy authenticated school academic year term class PGSID authorization credentials RBAC protected routes shared device log out'},
    {id:'mobile-help',title:'Mobile Help',body:'Purpose: use guide search, contextual Help, walkthroughs and concise tooltips on touch devices. Steps: select ? Help or User Guide, search or vertically scroll the guide, use Start walkthrough and Previous/Next/Skip/Close controls, then dismiss the overlay with Close Guide, Skip, Close or Escape where a keyboard is available. Warning: guidance is never hover-only; overlays are scrollable and dismissible so they do not permanently block navigation. Related modules: User Guide and all visible School modules.',keywords:'mobile help Android iPhone tablet touch vertical scrolling dismissible overlay tooltip walkthrough'},
    {id:'info-session',title:'Info & Session',body:'Purpose: explain the fixed final School sidebar items. User Guide reopens this assistance system. Copyright opens official copyright information. Acknowledgement opens official acknowledgements. Developer opens developer information only and does not grant developer privileges. Log Out safely ends the authenticated School session; always use it on shared devices. The exact final sidebar order is User Guide → Copyright → Acknowledgement → Developer → Log Out, and nothing appears after Log Out.',keywords:'info session user guide copyright acknowledgement developer log out logout developer privileges'}
  ];
  function school(){try{return localStorage.getItem('v43_login_level')==='SCHOOL'}catch(e){return false}}
  function esc(v){return String(v||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function visible(label){var n=document.querySelector('[data-school-nav="'+CSS.escape(label)+'"]');if(!n)return false;for(var p=n;p;p=p.parentElement){if(p.hidden||(getComputedStyle(p).display==='none'&&!p.classList.contains('nav-group-items')))return false}return true}
  function current(){var n=document.querySelector('#sg-school-level .school-nav-item.active');return n?n.dataset.schoolNav:'Dashboard'}
  function allowed(){return SECTIONS.filter(function(section){return (!section.access||visible(section.access))&&(section.id!=='admission'||visible('New Student Admission'))})}
  function style(){if(document.getElementById('edutrack-school-guide-style'))return;var s=document.createElement('style');s.id='edutrack-school-guide-style';s.textContent='.esg-help{position:fixed;right:max(1rem,env(safe-area-inset-right));bottom:max(1rem,env(safe-area-inset-bottom));z-index:99990;border:0;border-radius:999px;background:#087f8c;color:#fff;min-height:48px;padding:.7rem 1rem;font-weight:700;box-shadow:0 8px 24px #0004;cursor:pointer;touch-action:manipulation}.esg-overlay{position:fixed;inset:0;z-index:99999;background:#071a2fcc;display:grid;place-items:center;padding:1rem;box-sizing:border-box}.esg-dialog{width:min(760px,100%);max-height:min(86dvh,760px);overflow:auto;background:#fff;border-radius:16px;color:#152238;box-shadow:0 18px 60px #0008;padding:clamp(1rem,3vw,2rem);font-family:system-ui,sans-serif}.esg-top{display:flex;gap:.75rem;align-items:flex-start;justify-content:space-between}.esg-top h2{margin:0}.esg-close,.esg-actions button{min-height:44px;border:0;border-radius:8px;padding:.6rem .8rem;cursor:pointer;touch-action:manipulation}.esg-close{background:#e8eef5}.esg-search{width:100%;box-sizing:border-box;margin:1rem 0;padding:.75rem;border:1px solid #b8c7d9;border-radius:8px;font:inherit}.esg-section{border:1px solid #dbe5ee;border-radius:10px;margin:.65rem 0}.esg-section summary{cursor:pointer;padding:.8rem;font-weight:700}.esg-section p{padding:0 .8rem .8rem;line-height:1.5}.esg-actions{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:1rem}.esg-primary{background:#087f8c;color:#fff}.esg-tour{outline:4px solid #f4bb32!important;outline-offset:4px;border-radius:8px}@media(max-width:600px){.esg-overlay{padding:.45rem}.esg-dialog{max-height:94dvh;border-radius:12px}.esg-help{min-height:48px}}@media(prefers-reduced-motion:reduce){.esg-tour{transition:none}}';document.head.appendChild(s)}
  function close(){var n=document.getElementById('edutrack-school-guide-overlay');if(n)n.remove();document.querySelectorAll('.esg-tour').forEach(function(x){x.classList.remove('esg-tour')})}
  var WALKTHROUGHS={
    'Score Entry':['Score Entry'],'Multi-Subject Entry':['Multi-Subject Entry'],'Mock Entry':['Mock Entry'],'Learning Management (LMS)':['Learning Management (LMS)'],'Attendance Register':['Attendance Register'],'User Accounts & Access Control':['User Accounts & Access Control'],'Assign Class to Teachers':['Assign Class to Teachers'],'Reassign Class':['Reassign Class'],'Assign Roles':['Assign Roles'],'Student Admission & Transfer Management':['New Student Admission','Transfer Admission','Student Search / Profile'],'Publish Results':['Publish Results'],'Fee Hub':['FMS Dashboard','Record Payment'],'Reports':['School Report Generator','Academic Year Report'],'Cloud Sync':['Cloud Sync'],'Student Database':['Student Database'],'Result Slip':['Result Slip'],'Broadsheet':['Broadsheet'],'Timetable AI':['Timetable AI'],'AI Analytics Engine':['AI Analytics Engine'],'Online Admission':['Online Admission'],'Admissions Review':['Admissions Review'],'QR Attendance':['QR Attendance']
  };
  var CONTROL_HELP={'Save Score':'Save the entered scores for the currently selected authorized class, subject and assessment scope.','Save Scores':'Save the entered scores for the currently selected authorized class, subject and assessment scope.','Publish Results':'Make the selected existing result scope visible according to current authorization and publication rules.','Block Result':'Withdraw result visibility under the existing rules; this does not delete underlying scores.','Cloud Sync':'Review current sync status before starting an authorized school sync.','PGSID':'The learner permanent identity. Search and verify it before admission, transfer or payment.','Record Payment':'Verify the learner name, PGSID, fee and amount before recording payment.','Generate':'Create the current report, result or output for the selected scope; review filters first.','Approve':'Progress the current authorized application or request after reviewing its details.','Reject':'Decline the current authorized application or request; supply a reason where the existing form requires one.'};
  function labelsFor(topic){return WALKTHROUGHS[topic]||['Dashboard','Setup / Config','New Student Admission','User Guide']}
  function targets(topic){return labelsFor(topic).map(function(label){return document.querySelector('[data-school-nav="'+CSS.escape(label)+'"]')}).filter(function(n){return n&&visible(n.dataset.schoolNav)})}
  function render(query){if(!school())return;style();close();var q=String(query||'').toLowerCase(),topic=current(),sections=allowed().filter(function(x){return !q||(x.title+' '+x.body+' '+(x.keywords||'')).toLowerCase().includes(q)}),canWalk=targets(topic).length>0;var overlay=document.createElement('div');overlay.id='edutrack-school-guide-overlay';overlay.className='esg-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','EduTrack School User Guide');overlay.innerHTML='<div class="esg-dialog" tabindex="-1"><div class="esg-top"><div><p style="margin:0;color:#52627d;font-size:.85rem">School-level help · How to Use This Page: '+esc(topic)+'</p><h2>EduTrack User Guide</h2></div><button type="button" class="esg-close" data-guide-close>Close Guide</button></div><input class="esg-search" aria-label="Search this School User Guide" placeholder="Search School help…" value="'+esc(query||'')+'"><div data-guide-results>'+sections.map(function(x){return '<details class="esg-section" open><summary>'+esc(x.title)+'</summary><p>'+esc(x.body)+'</p></details>'}).join('')+(sections.length?'':'<p>No School-level guide topic matches that search.</p>')+'</div><div class="esg-actions">'+(canWalk?'<button type="button" class="esg-primary" data-guide-walkthrough>Start walkthrough</button>':'')+'<button type="button" data-guide-tour>Restart Tour</button><button type="button" data-guide-close>Close Guide</button></div></div>';document.body.appendChild(overlay);var dialog=overlay.querySelector('.esg-dialog');dialog.focus();overlay.querySelectorAll('[data-guide-close]').forEach(function(b){b.onclick=close});overlay.addEventListener('click',function(e){if(e.target===overlay)close()});overlay.querySelector('.esg-search').addEventListener('input',function(e){render(e.target.value)});overlay.querySelector('[data-guide-tour]').onclick=function(){close();tour(0)};var start=overlay.querySelector('[data-guide-walkthrough]');if(start)start.onclick=function(){close();tour(0,topic)};overlay.addEventListener('keydown',function(e){if(e.key==='Escape')close()})}
  function tour(index,topic){if(!school())return;var steps=targets(topic);if(!steps.length)return;var node=steps[index];node.classList.add('esg-tour');var box=document.createElement('div');box.className='esg-overlay';box.id='edutrack-school-guide-overlay';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.innerHTML='<div class="esg-dialog" style="max-width:430px"><p style="margin:0;color:#52627d">'+esc(topic?'Walkthrough: '+topic:'First-login tour')+' · Step '+(index+1)+' of '+steps.length+'</p><h2 style="margin:.3rem 0">'+esc(node.dataset.schoolNav)+'</h2><p>Use this visible, authorized School navigation item to open its existing page. The guide explains prerequisites, steps, save/generate behavior, warnings and related modules.</p><div class="esg-actions">'+(index>0?'<button type="button" data-tour-previous>Previous</button>':'')+'<button type="button" data-tour-skip>Skip</button><button type="button" data-tour-close>Close</button><button type="button" class="esg-primary" data-tour-next>'+(index===steps.length-1?'Finish':'Next')+'</button></div></div>';document.body.appendChild(box);function done(){try{localStorage.setItem(TOUR_KEY,'true')}catch(e){}close()}box.querySelector('[data-tour-skip]').onclick=done;box.querySelector('[data-tour-close]').onclick=close;var previous=box.querySelector('[data-tour-previous]');if(previous)previous.onclick=function(){node.classList.remove('esg-tour');box.remove();tour(index-1,topic)};box.querySelector('[data-tour-next]').onclick=function(){node.classList.remove('esg-tour');if(index===steps.length-1)done();else{box.remove();tour(index+1,topic)}}}
  function help(){render('');}
  function tooltips(root){(root||document).querySelectorAll('button,input[type="submit"],input[title]').forEach(function(n){var key=(n.value||n.textContent||n.getAttribute('title')||'').trim().replace(/\s+/g,' '),help=CONTROL_HELP[key];if(help){n.title=help;n.setAttribute('aria-label',key+'. '+help)}})}
  function install(){if(!school())return;style();var titles={};allowed().forEach(function(s){titles[s.title]=s});document.querySelectorAll('#sg-school-level [data-school-nav]').forEach(function(n){var s=titles[n.dataset.schoolNav];if(s)n.title='Help available: '+s.title});tooltips();if(!window.__edutrackSchoolGuideTooltips){window.__edutrackSchoolGuideTooltips=true;new MutationObserver(function(records){records.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===1)tooltips(n)})})}).observe(document.body,{childList:true,subtree:true})}if(!document.getElementById('edutrack-school-context-help')){var b=document.createElement('button');b.id='edutrack-school-context-help';b.type='button';b.className='esg-help';b.textContent='? Help';b.setAttribute('aria-label','How to use '+current());b.onclick=function(){render(current())};document.body.appendChild(b)}try{if(!localStorage.getItem(TOUR_KEY))setTimeout(function(){tour(0)},700)}catch(e){}}
  window.EDUTRACK_SCHOOL_GUIDE={open:help,close:close,restart:function(){close();tour(0)},context:function(){render(current())},install:install};
  window.addEventListener('edutrack:school-general-ready',install);
  if(school())install();
})();
